/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <p>
 * The store can check and repair this index and its files while initializing.  This is controlled by
 * {@code default.integrity}, which accepts {@code ignore}, {@code repair}, and {@code fail}.
 *
 * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final Pattern BUILT_IN_FILE_NAME_PATTERN = Pattern.compile("[A-Za-z0-9_-]+");

    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String RANDOM_FILE_NAMES = "random";
    private static final String DESCRIPTION_FILE_NAMES = "description";
    private static final String REPAIR_INTEGRITY = "repair";
    private static final String FAIL_INTEGRITY = "fail";
    private static final String IGNORE_INTEGRITY = "ignore";

    private static final Map<String, StoreState> STORES_BY_PATH = new HashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean hasConstructorStrategy;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private IntegrityMode integrityMode;
    private File storeFolder;
    private StoreState storeState;

    /**
     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        hasConstructorStrategy = false;
    }

    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        constructorStrategy = checkNotNull(ruleViolationFileNameStrategy);
        hasConstructorStrategy = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));

        RuleViolationFileNameStrategy strategy = namingStrategy(properties);
        initializedStrategy = strategy;
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Repairing the violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }
        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
        storeFolder = new File(path);
        String stateKey = canonicalPath(storeFolder);
        StoreState state = stateFor(stateKey, storeFolder);

        synchronized (state.lock) {
            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), new File(storeFolder, STORED_RULES_FILE_NAME).getAbsolutePath());
            Path folderPath = storeFolder.toPath();
            Path storedRulesPath = folderPath.resolve(STORED_RULES_FILE_NAME);
            boolean indexExisted = Files.exists(storedRulesPath, LinkOption.NOFOLLOW_LINKS);
            if (!indexExisted && !storeCreationAllowed) {
                throw new StoreInitializationFailedException(String.format(
                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
            }

            ensureFolder(folderPath);

            if (!indexExisted && integrityMode == IntegrityMode.FAIL) {
                // Do the only useful part of the check without creating the index.  In particular, a failed
                // fail-mode initialization must not leave an index behind.
                List<String> unowned = unownedFiles(folderPath, null);
                if (!unowned.isEmpty()) {
                    throw integrityFailure(Collections.<Entry>emptyList(), unowned);
                }
            }

            if (!indexExisted) {
                createIndex(storedRulesPath);
                indexExisted = true;
            }
            if (!Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "The violation store index must be a regular file directly in %s", storeFolder.getAbsolutePath()));
            }

            Properties propertiesFromDisk = loadProperties(storedRulesPath);
            state.folder = storeFolder;
            state.index = storedRulesPath;
            if (integrityMode == IntegrityMode.REPAIR) {
                state.rules = propertiesFromDisk;
                state.rules = repair(state, strategy, propertiesFromDisk);
            } else if (integrityMode == IntegrityMode.FAIL) {
                List<Entry> entries = inspectEntries(folderPath, propertiesFromDisk, strategy);
                List<String> unowned = unownedFiles(folderPath, entries);
                if (hasIntegrityProblems(entries, unowned)) {
                    throw integrityFailure(entries, unowned);
                }
                state.rules = propertiesFromDisk;
            } else {
                state.rules = propertiesFromDisk;
            }
            storeState = state;
        }
    }

    private RuleViolationFileNameStrategy namingStrategy(Properties properties) {
        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
        if (hasConstructorStrategy) {
            if (configured != null) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            return constructorStrategy;
        }
        if (configured == null || RANDOM_FILE_NAMES.equals(configured)) {
            return __ -> UUID.randomUUID().toString();
        }
        if (DESCRIPTION_FILE_NAMES.equals(configured)) {
            return TextFileBasedViolationStore::descriptionFileName;
        }
        try {
            Class<?> type = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(type)) {
                throw new Exception("not a RuleViolationFileNameStrategy");
            }
            if (!Modifier.isPublic(type.getModifiers())) {
                throw new Exception("the class is not public");
            }
            Constructor<?> constructor = type.getConstructor();
            Constructor<?> constructor = type.getConstructor();
            if (!Modifier.isPublic(constructor.getModifiers())) {
                throw new Exception("the constructor is not public");
            }
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "%s must be random, description, or the fully-qualified name of a RuleViolationFileNameStrategy with a public no-argument constructor: %s",
                    FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    private static String descriptionFileName(String description) {
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        String selectedWord = null;
        while (matcher.find()) {
            String word = matcher.group(1);
            if (selectedWord == null || word.length() > selectedWord.length()) {
                selectedWord = word;
            }
        }
        String digest = digest(description);
        String result = (selectedWord == null ? "rule" : selectedWord) + "-" + digest;
        if (!BUILT_IN_FILE_NAME_PATTERN.matcher(result).matches() || result.length() > 200 || STORED_RULES_FILE_NAME.equals(result)) {
            // The construction above is deliberately conservative, but keep the invariant local to this built-in
            // strategy in case its implementation is changed later.
            result = "rule-" + digest;
        }
        return result;
    }

    private static String digest(String description) {
        try {
            byte[] bytes = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
            StringBuilder result = new StringBuilder(bytes.length * 2);
            for (byte value : bytes) {
                result.append(String.format("%02x", value & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private static String canonicalPath(File file) {
        try {
            return file.getCanonicalPath();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static StoreState stateFor(String key, File folder) {
        synchronized (STORES_BY_PATH) {
            StoreState result = STORES_BY_PATH.get(key);
            if (result == null) {
                result = new StoreState(folder);
                STORES_BY_PATH.put(key, result);
            }
            return result;
        }
    }

    private static void ensureFolder(Path folder) {
        try {
            if (!Files.exists(folder, LinkOption.NOFOLLOW_LINKS)) {
                Files.createDirectories(folder);
            }
            if (!Files.isDirectory(folder)) {
                throw new StoreInitializationFailedException(String.format("The violation store path is not a folder: %s", folder));
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static void createIndex(Path index) {
        try {
            Files.createFile(index);
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private static Properties loadProperties(Path index) {
        Properties result = new Properties();
        try (InputStream input = Files.newInputStream(index)) {
            result.load(input);
            return result;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storeState.lock) {
            return storedRuleKey(rule.getDescription()) != null;
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storeState.lock) {
            String description = rule.getDescription();
            String key = storedRuleKey(description);
            String existingName = key == null ? null : storeState.rules.getProperty(key);
            if (key == null) {
                key = description;
            }
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                if (existingName != null) {
                    forgetKnownRule(key, existingName);
                }
                return;
            }
            if (violations.isEmpty() && existingName == null && integrityMode == IntegrityMode.REPAIR) {
                return;
            }

            String name = existingName == null ? deriveName(description) : existingName;
            Path target = checkedSaveTarget(name, key, existingName);
            if (existingName == null && Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreUpdateFailedException(String.format("Cannot store rule '%s': its file name is already occupied: %s", description, name));
            }

            if (existingName == null) {
                writeNewFile(target, violations);
                Properties updated = copyOf(storeState.rules);
                updated.setProperty(key, normalizeValue(name));
                try {
                    writeIndex(storeState.index, updated);
                    storeState.rules = updated;
                } catch (RuntimeException e) {
                    deletePath(target);
                    throw e;
                }
            } else {
                writeExistingFile(target, violations);
            }
        }
    }

    private void forgetKnownRule(String key, String name) {
        Path file = pathForName(name);
        if (!isSharedWithAnotherEntry(key, name)) {
            try {
                deleteStoredFile(file);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
        Properties updated = copyOf(storeState.rules);
        updated.remove(key);
        writeIndex(storeState.index, updated);
        storeState.rules = updated;
    }

    private boolean isSharedWithAnotherEntry(String key, String name) {
        for (String otherKey : storeState.rules.stringPropertyNames()) {
            if (!otherKey.equals(key) && sameStoredName(name, storeState.rules.getProperty(otherKey))) {
                return true;
            }
        }
        Path file = safePathForName(storeFolder.toPath(), name);
        if (file == null || !Files.isRegularFile(file)) {
            return false;
        }
        for (String otherKey : storeState.rules.stringPropertyNames()) {
            if (otherKey.equals(key)) {
                continue;
            }
            Path other = safePathForName(storeFolder.toPath(), storeState.rules.getProperty(otherKey));
            if (other != null && sameFile(file, other)) {
                return true;
            }
        }
        return false;
    }

    private static boolean sameStoredName(String first, String second) {
        return first == null ? second == null : first.equals(second);
    }

    private Path checkedSaveTarget(String name, String key, String existingName) {
        Path target = pathForName(name);
        Path index = storeState.index;
        if (samePath(target, index) || (Files.exists(target, LinkOption.NOFOLLOW_LINKS) && sameFile(target, index))) {
            throw new StoreUpdateFailedException("A rule violation file must not lead to stored.rules");
        }
        if (existingName != null && !sameStoredName(name, existingName)) {
            throw new StoreUpdateFailedException(String.format("Rule '%s' does not record file name '%s'", key, name));
        }
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
            if (!Files.isRegularFile(target)) {
                throw new StoreUpdateFailedException(String.format("Rule violation file is not regular: %s", name));
            }
            Path realParent = realParent(target);
            Path folderReal = realPath(storeFolder.toPath());
            if (realParent == null || !folderReal.equals(realParent)) {
                throw new StoreUpdateFailedException(String.format("Rule violation file does not lead directly into the store folder: %s", name));
            }
        }
        return target;
    }

    private void writeNewFile(Path target, List<String> violations) {
        if (target.getParent() == null) {
            throw new StoreUpdateFailedException("Invalid rule violation file path: " + target);
        }
        writeBytes(target, violationText(violations), false);
    }

    private void writeExistingFile(Path target, List<String> violations) {
        writeBytes(target, violationText(violations), true);
    }

    private void writeBytes(Path target, byte[] bytes, boolean existing) {
        try {
