    private Properties repair(StoreState state, RuleViolationFileNameStrategy strategy, Properties original) {
        List<Entry> entries = inspectEntries(state.folder.toPath(), original, strategy);
        Properties repaired = copyOf(original);
        boolean changed = false;
        for (Entry entry : entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.indexFile) {
                repaired.remove(entry.description);
                changed = true;
                continue;
            }
            if (entry.broken) {
                repaired.remove(entry.description);
                changed = true;
            } else if (entry.resolved) {
                try {
                    deleteStoredFile(entry.path);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException(e);
                }
                repaired.remove(entry.description);
                changed = true;
            }
        }
        for (Entry entry : entries) {
            if (entry.indexFile || entry.shared || entry.broken || entry.resolved || !entry.misplaced || entry.colliding || entry.occupied) {
                continue;
