    private static void deleteStoredFile(Path file) throws IOException {
        if (!Files.exists(file, LinkOption.NOFOLLOW_LINKS)) {
            return;
        }
        if (Files.isSymbolicLink(file)) {
            Path target = file.toRealPath();
            Files.delete(target);
            Files.deleteIfExists(file);
        } else {
            Files.delete(file);
        }
