    private List<Entry> inspectEntries(Path folder, Properties properties, RuleViolationFileNameStrategy strategy) {
        List<Entry> entries = new ArrayList<>();
        for (String description : properties.stringPropertyNames()) {
            String name = properties.getProperty(description);
            Path path = safePathForName(folder, name);
            boolean broken = path == null || !Files.isRegularFile(path);
            boolean indexFile = path != null && Files.isRegularFile(path) && sameFile(path, folder.resolve(STORED_RULES_FILE_NAME));
            boolean resolved = false;
            if (!broken && !indexFile) {
                try {
                    resolved = readLines(path).isEmpty();
                } catch (RuntimeException e) {
                    broken = true;
                }
            }
            entries.add(new Entry(description, name, path, broken, resolved, indexFile));
        }

        markShared(entries);
        Map<String, List<Entry>> derivedNames = new LinkedHashMap<>();
        for (Entry entry : entries) {
            if (randomFileNames) {
                entry.derivedName = entry.name;
                entry.derivedPath = entry.path;
                continue;
            }
            entry.derivedName = deriveNameForInspection(strategy, entry.description);
            entry.derivedPath = safePathForName(folder, entry.derivedName);
            entry.misplaced = !sameStoredName(entry.name, entry.derivedName);
            if (entry.derivedName != null) {
                derivedNames.computeIfAbsent(entry.derivedName, __ -> new ArrayList<>()).add(entry);
            }
        }
        for (List<Entry> collision : derivedNames.values()) {
            if (collision.size() > 1) {
                for (Entry entry : collision) {
                    entry.colliding = true;
                }
            }
        }
        for (Entry entry : entries) {
            if (!entry.misplaced) {
                continue;
            }
            entry.occupied = entry.derivedPath == null
                    || !isDirectPath(folder, entry.derivedPath)
                    || hasOtherEntryWithName(entries, entry, entry.derivedName)
                    || Files.exists(entry.derivedPath, LinkOption.NOFOLLOW_LINKS);
        }
        return entries;
