                .append(storeUpdateAllowed).append(")");
        appendEntries(message, "broken", entries, entry -> (entry.broken || entry.indexFile) && !entry.shared);
        appendEntries(message, "resolved", entries, entry -> entry.resolved && !entry.shared);
        appendEntries(message, "shared", entries, entry -> entry.shared);
        appendEntries(message, "misplaced", entries, entry -> entry.misplaced && !entry.shared);
        appendEntries(message, "colliding", entries, entry -> entry.colliding && !entry.shared);
        appendEntries(message, "occupied", entries, entry -> entry.occupied && !entry.shared);
        if (!unowned.isEmpty()) {
            message.append("\nunowned files:");
            List<String> sorted = new ArrayList<>(unowned);
            Collections.sort(sorted);
            for (String file : sorted) {
