                .sorted(Comparator.comparing(entry -> entry.description))
                .collect(toList());
        if (matching.isEmpty()) {
            return;
        }
        message.append('\n').append(condition).append(" entries:");
        for (Entry entry : matching) {
            message.append("\n  ").append(entry.description).append(" -> ").append(entry.name);
